// Calcular fecha de lookback basada en Lookback_Days
const lookbackDays = $input.item.json.Lookback_Days || 30;
const lookbackDate = new Date();
lookbackDate.setDate(lookbackDate.getDate() - lookbackDays);

// Formato ISO para WordPress API
const isoDate = lookbackDate.toISOString();

// Construir la URL de la API de WordPress
const siteUrl = $input.item.json.Sitio_URL;
const apiUrl = `${siteUrl}/wp-json/wp/v2/posts?after=${isoDate}&per_page=20&_embed&orderby=date&order=desc`;

return {
  json: {
    ...($input.item.json),
    lookback_date: isoDate,
    wp_api_url: apiUrl,
    site_domain: new URL(siteUrl).hostname
  }
};

// Extraer y limpiar contenido de artículos
const articles = $input.item.json;
const siteData = $input.first().json;

// Si no hay artículos, retornar estructura vacía
if (!Array.isArray(articles) || articles.length === 0) {
  return {
    json: {
      ...siteData,
      articles: [],
      has_content: false
    }
  };
}

// Función para limpiar HTML y extraer primeros párrafos
function extractFirstParagraphs(htmlContent, maxParagraphs = 3) {
  // Remover scripts, styles, y tags complejos
  let cleaned = htmlContent
    .replace(/<script[^>]*>.*?<\/script>/gis, '')
    .replace(/<style[^>]*>.*?<\/style>/gis, '')
    .replace(/<\/?[^>]+(>|$)/g, ' ')  // Remover todas las tags HTML
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\s+/g, ' ')  // Normalizar espacios
    .trim();

  // Dividir en párrafos (por punto seguido de espacio y mayúscula)
  const paragraphs = cleaned.split(/\.\s+(?=[A-Z])/).filter(p => p.trim().length > 50);

  // Tomar solo los primeros N párrafos
  const selectedParagraphs = paragraphs.slice(0, maxParagraphs).join('. ');

  // Limitar a ~1000 caracteres para optimizar costos de AI
  return selectedParagraphs.substring(0, 1000) + (selectedParagraphs.length > 1000 ? '...' : '');
}

// Procesar cada artículo
const processedArticles = articles.map(article => {
  const content = article.content?.rendered || article.excerpt?.rendered || '';
  const extractedContent = extractFirstParagraphs(content, 3);

  return {
    title: article.title?.rendered || 'Sin título',
    url: article.link || article.guid?.rendered || '',
    date: article.date || new Date().toISOString(),
    excerpt_for_ai: extractedContent,
    word_count: extractedContent.split(/\s+/).length
  };
}).filter(article => article.word_count > 20); // Filtrar artículos muy cortos

return {
  json: {
    ...siteData,
    articles: processedArticles,
    total_articles: processedArticles.length,
    has_content: processedArticles.length > 0
  }
};

