// Extraer el insight generado por Claude
const response = $input.item.json;
const article = $input.first().json.current_article;
const siteData = $input.first().json;

// Parsear respuesta de Anthropic
let insight = 'Información relevante sobre infraestructura y logística.';

if (response.content && Array.isArray(response.content) && response.content.length > 0) {
  insight = response.content[0].text || insight;
  // Limpiar y limitar a 250 caracteres
  insight = insight.trim().substring(0, 250);
  // Asegurar que termine en punto si fue cortado
  if (insight.length === 250 && !insight.endsWith('.')) {
    insight = insight.substring(0, 247) + '...';
  }
}

return {
  json: {
    ...siteData,
    processed_article: {
      title: article.title,
      url: article.url,
      date: article.date,
      insight: insight
    }
  }
};

// Agregar artículo procesado a la lista acumulada
const allItems = $input.all();
const processedArticles = allItems.map(item => item.json.processed_article);

// Recuperar datos del sitio
const siteData = $input.first().json;

return {
  json: {
    ...siteData,
    processed_articles: processedArticles
  }
};

// Construir el archivo llms.txt completo
const siteData = $input.item.json;
const processedArticles = siteData.processed_articles || [];
const siteDomain = siteData.site_domain || new URL(siteData.Sitio_URL).hostname;
const siteUrl = siteData.Sitio_URL;

// Header del archivo llms.txt
const header = `# ${siteDomain}

> Portal de Infraestructura y Logística - Insights de Impacto para Deep Research
> Actualizado: ${new Date().toISOString().split('T')[0]}
> Artículos procesados: ${processedArticles.length}

## Recursos principales

- Sitio web: ${siteUrl}
- RSS Feed: ${siteUrl}/feed/
- API: ${siteUrl}/wp-json/wp/v2/

---

## Insights de Impacto Recientes

`;

// Construir sección de artículos
const articlesSection = processedArticles.map((article, index) => {
  return `### ${index + 1}. [${article.title}](${article.url})

**Insight:** ${article.insight}

**Fecha:** ${new Date(article.date).toISOString().split('T')[0]}

---
`;
}).join('\n');

// Footer
const footer = `
## Sobre este archivo

Este archivo llms.txt ha sido generado automáticamente para optimizar la recuperación de información por modelos de lenguaje de gran escala (LLMs). Los insights presentados están diseñados para:

- Investigación profunda (Deep Research)
- Análisis de inversiones en infraestructura
- Inteligencia de mercado logístico
- Toma de decisiones basada en datos

**Metodología:** Extracción automática de métricas clave, cifras financieras y análisis de impacto mediante AI.

**Actualización:** Este archivo se regenera automáticamente cada ${siteData.Lookback_Days || 30} días.

**Contacto:** Para más información, visite ${siteUrl}
`;

// Archivo completo
const llmsTxtContent = header + articlesSection + footer;

return {
  json: {
    ...siteData,
    llms_txt_content: llmsTxtContent,
    llms_txt_filename: 'llms.txt',
    file_size: Buffer.from(llmsTxtContent, 'utf-8').length,
    ready_for_upload: true
  }
};

// Log de resultados para monitoreo
const siteData = $input.item.json;

const logEntry = {
  timestamp: new Date().toISOString(),
  site: siteData.site_domain,
  articles_processed: siteData.processed_articles?.length || 0,
  file_size: siteData.file_size || 0,
  status: siteData.ready_for_upload ? 'SUCCESS' : 'FAILED',
  sftp_host: siteData.sFTP_Host
};

console.log('✅ Sitio procesado:', JSON.stringify(logEntry, null, 2));

return {
  json: logEntry
};

// Manejo de sitios sin contenido nuevo
const siteData = $input.item.json;

const logEntry = {
  timestamp: new Date().toISOString(),
  site: siteData.site_domain,
  articles_processed: 0,
  status: 'SKIPPED - No new content',
  lookback_days: siteData.Lookback_Days
};

console.log('⚠️ Sitio sin contenido nuevo:', JSON.stringify(logEntry, null, 2));

return {
  json: logEntry
};

// Generar reporte final consolidado
const allResults = $input.all().map(item => item.json);

const summary = {
  execution_timestamp: new Date().toISOString(),
  total_sites_processed: allResults.length,
  successful_uploads: allResults.filter(r => r.status === 'SUCCESS').length,
  skipped_sites: allResults.filter(r => r.status?.includes('SKIPPED')).length,
  total_articles_processed: allResults.reduce((sum, r) => sum + (r.articles_processed || 0), 0),
  total_file_size_bytes: allResults.reduce((sum, r) => sum + (r.file_size || 0), 0),
  results: allResults
};

console.log('\n📊 REPORTE FINAL DE EJECUCIÓN:\n', JSON.stringify(summary, null, 2));

return {
  json: summary
};
